"use client";
import React, { JSX, useState, useEffect } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { useAuth } from "../context/AuthContext";
import ErrorMessage from "../components/shared/ErrorMessage";
import { Eye, EyeOff } from "lucide-react";
import { useGoogleLogin } from '@react-oauth/google';

export default function SignUpPage(): JSX.Element {
  const router = useRouter();
  const { register, loginWithGoogle, loginWithFacebook } = useAuth();

  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [phone, setPhone] = useState("");
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [emailWarning, setEmailWarning] = useState<string | null>(null);
  const [phoneWarning, setPhoneWarning] = useState<string | null>(null);
  const [passwordWarning, setPasswordWarning] = useState<string | null>(null);
  const [passwordMatchWarning, setPasswordMatchWarning] = useState<string | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);

  // Email validation (optional)
  const validateEmail = (email: string) => {
    if (!email) {
      setEmailWarning(null);
      return;
    }
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (email && !emailRegex.test(email)) {
      setEmailWarning('Please enter a valid email address');
    } else {
      setEmailWarning(null);
    }
  };

  // Phone validation (required)
  const validatePhone = (phone: string) => {
    const phoneRegex = /^[\+]?[(]?[0-9]{1,4}[)]?[-\s\.]?[(]?[0-9]{1,4}[)]?[-\s\.]?[0-9]{1,9}$/;
    if (!phone) {
      setPhoneWarning('Phone number is required');
    } else if (!phoneRegex.test(phone)) {
      setPhoneWarning('Please enter a valid phone number');
    } else {
      setPhoneWarning(null);
    }
  };

  // Password strength validation
  const validatePasswordStrength = (password: string) => {
    if (!password) {
      setPasswordWarning(null);
      return;
    }

    if (password.length < 8) {
      setPasswordWarning('Password must be at least 8 characters long');
    } else if (!/(?=.*[a-z])(?=.*[A-Z])(?=.*\d)/.test(password)) {
      setPasswordWarning('Password should contain uppercase, lowercase, and numbers');
    } else {
      setPasswordWarning(null);
    }
  };

  // Password match validation
  const validatePasswordMatch = (password: string, confirmPassword: string) => {
    if (confirmPassword && password !== confirmPassword) {
      setPasswordMatchWarning('Passwords do not match');
    } else {
      setPasswordMatchWarning(null);
    }
  };

  const handleEmailChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    setEmail(value);
    validateEmail(value);
  };

  const handlePhoneChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    setPhone(value);
    validatePhone(value);
  };

  const handlePasswordChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    setPassword(value);
    validatePasswordStrength(value);
    validatePasswordMatch(value, confirmPassword);
  };

  const handleConfirmPasswordChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    setConfirmPassword(value);
    validatePasswordMatch(password, value);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setSuccessMessage(null);

    // Validation checks
    if (!name || !phone || !password || !confirmPassword) {
      setError("Please fill in all required fields");
      return;
    }

    if (phoneWarning || emailWarning || passwordWarning || passwordMatchWarning) {
      setError("Please fix all errors before submitting");
      return;
    }

    if (password !== confirmPassword) {
      setError("Passwords do not match");
      return;
    }

    setLoading(true);
    try {
      const result = await register(name, phone, password, email || undefined);
      if (result.success) {
        setSuccessMessage('Account created successfully! Redirecting...');
        // Delay redirect to show success message, same as login flow
        setTimeout(() => {
          router.push("/");
        }, 1000);
      } else {
        setError(result.error || "Registration failed");
      }
    } catch (err: any) {
      setError(err?.message || "Registration failed");
    } finally {
      setLoading(false);
    }
  };

  const googleLogin = useGoogleLogin({
    flow: 'auth-code',
    onSuccess: async (codeResponse) => {
      setLoading(true);
      try {
        const result = await loginWithGoogle(codeResponse.code); // Send code to backend
        if (result.success) {
          setSuccessMessage('Account created successfully! Redirecting...');
          setTimeout(() => {
            router.push("/");
          }, 1000);
        } else {
          setError(result.error || 'Google signup failed');
        }
      } catch (err: any) {
        setError(err?.message || 'Google signup failed');
      } finally {
        setLoading(false);
      }
    },
    onError: (errorResponse) => {
      console.error('Google Signup Error:', errorResponse);
      setError('Google signup failed');
    },
  });

  const handleFacebookLogin = () => {
    // Initialize Facebook SDK and login
    if (typeof window !== 'undefined' && (window as any).FB) {
      (window as any).FB.login((response: any) => {
        if (response.authResponse) {
          setLoading(true);
          loginWithFacebook(response.authResponse.accessToken, response.authResponse.userID)
            .then((result) => {
              if (result.success) {
                setSuccessMessage('Account created successfully! Redirecting...');
                setTimeout(() => {
                  router.push('/');
                }, 1000);
              } else {
                setError(result.error || 'Facebook signup failed');
              }
            })
            .catch((err) => {
              setError(err?.message || 'Facebook signup failed');
            })
            .finally(() => {
              setLoading(false);
            });
        } else {
          setError('Facebook signup cancelled');
        }
      }, { scope: 'public_profile,email' });
    } else {
      setError('Facebook SDK not loaded');
    }
  };

  // Load Facebook SDK
  useEffect(() => {
    if (typeof window !== 'undefined') {
      (window as any).fbAsyncInit = function () {
        (window as any).FB.init({
          appId: process.env.NEXT_PUBLIC_FACEBOOK_APP_ID,
          cookie: true,
          xfbml: true,
          version: 'v18.0'
        });
      };

      // Load the SDK asynchronously
      (function (d, s, id) {
        var js: any, fjs: any = d.getElementsByTagName(s)[0];
        if (d.getElementById(id)) return;
        js = d.createElement(s); js.id = id;
        js.src = "https://connect.facebook.net/en_US/sdk.js";
        fjs.parentNode.insertBefore(js, fjs);
      }(document, 'script', 'facebook-jssdk'));
    }
  }, []);

  return (
    <div className="flex justify-center items-center min-h-screen bg-gray-50 py-8">
      <form
        onSubmit={handleSubmit}
        className="flex flex-col gap-3 bg-white p-8 w-full max-w-md rounded-2xl shadow-md font-[system-ui]"
      >
        <h2 className="text-2xl font-semibold text-gray-800 mb-1 text-center">
          Create an Account
        </h2>
        <p className="text-sm text-gray-600 text-center mb-4">
          Join us and start using Dosro Bazar today
        </p>

        {/* Full Name */}
        <div className="flex flex-col">
          <label className="text-gray-800 font-semibold mb-1" htmlFor="name">
            Full Name <span className="text-red-500">*</span>
          </label>
          <div className="flex items-center border border-gray-200 rounded-lg h-12 px-3 focus-within:border-blue-500 transition">
            <input
              id="name"
              type="text"
              value={name}
              autoComplete="off"
              onChange={(e) => setName(e.target.value)}
              placeholder="Enter your full name"
              className="w-full border-none outline-none bg-transparent text-gray-700 placeholder-gray-400"
            />
          </div>
        </div>

        {/* Phone Number */}
        <div className="flex flex-col">
          <label className="text-gray-800 font-semibold mb-1" htmlFor="phone">
            Phone Number <span className="text-red-500">*</span>
          </label>
          <div className={`flex items-center border rounded-lg h-12 px-3 transition ${phoneWarning ? 'border-amber-400 focus-within:border-amber-500' : 'border-gray-200 focus-within:border-blue-500'
            }`}>
            <input
              id="phone"
              type="tel"
              autoComplete="off"
              value={phone}
              onChange={handlePhoneChange}
              onBlur={() => validatePhone(phone)}
              placeholder="Enter your phone number"
              className="w-full border-none outline-none bg-transparent text-gray-700 placeholder-gray-400"
            />
          </div>
          {phoneWarning && (
            <div className="mt-2">
              <ErrorMessage variant="warning" message={phoneWarning} />
            </div>
          )}
        </div>

        {/* Email (Optional) */}
        <div className="flex flex-col">
          <label className="text-gray-800 font-semibold mb-1" htmlFor="email">
            Email <span className="text-gray-500 text-xs">(Optional)</span>
          </label>
          <div className={`flex items-center border rounded-lg h-12 px-3 transition ${emailWarning ? 'border-amber-400 focus-within:border-amber-500' : 'border-gray-200 focus-within:border-blue-500'
            }`}>
            <input
              id="email"
              type="email"
              autoComplete="off"
              value={email}
              onChange={handleEmailChange}
              onBlur={() => validateEmail(email)}
              placeholder="Enter your email (optional)"
              className="w-full border-none outline-none bg-transparent text-gray-700 placeholder-gray-400"
            />
          </div>
          {emailWarning && (
            <div className="mt-2">
              <ErrorMessage variant="warning" message={emailWarning} />
            </div>
          )}
        </div>

        {/* Password */}
        <div className="flex flex-col mt-3">
          <label className="text-gray-800 font-semibold mb-1" htmlFor="password">
            Password <span className="text-red-500">*</span>
          </label>
          <div className={`flex items-center border rounded-lg h-12 px-3 transition ${passwordWarning ? 'border-amber-400 focus-within:border-amber-500' : 'border-gray-200 focus-within:border-blue-500'
            }`}>
            <input
              id="password"
              type={showPassword ? "text" : "password"}
              autoComplete="off"
              value={password}
              onChange={handlePasswordChange}
              onBlur={() => validatePasswordStrength(password)}
              placeholder="Create a password"
              className="w-full border-none outline-none bg-transparent text-gray-700 placeholder-gray-400"
            />
            <button
              type="button"
              onClick={() => setShowPassword(!showPassword)}
              className="ml-2 text-gray-500 hover:text-gray-700"
            >
              {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
            </button>
          </div>
          {passwordWarning && (
            <div className="mt-2">
              <ErrorMessage variant="warning" message={passwordWarning} />
            </div>
          )}
        </div>

        {/* Confirm Password */}
        <div className="flex flex-col mt-3">
          <label
            className="text-gray-800 font-semibold mb-1"
            htmlFor="confirmPassword"
          >
            Confirm Password <span className="text-red-500">*</span>
          </label>
          <div className={`flex items-center border rounded-lg h-12 px-3 transition ${passwordMatchWarning ? 'border-amber-400 focus-within:border-amber-500' : 'border-gray-200 focus-within:border-blue-500'
            }`}>
            <input
              id="confirmPassword"
              type={showPassword ? "text" : "password"}
              autoComplete="off"
              value={confirmPassword}
              onChange={handleConfirmPasswordChange}
              onBlur={() => validatePasswordMatch(password, confirmPassword)}
              placeholder="Re-enter password"
              className="w-full border-none outline-none bg-transparent text-gray-700 placeholder-gray-400"
            />
          </div>
          {passwordMatchWarning && (
            <div className="mt-2">
              <ErrorMessage variant="warning" message={passwordMatchWarning} />
            </div>
          )}
        </div>

        {successMessage && <ErrorMessage variant="success" message={successMessage} />}
        {error && <ErrorMessage error={error} />}

        {/* Submit */}
        <button
          disabled={loading}
          type="submit"
          className="w-full mt-4 bg-gray-900 text-white py-3 rounded-lg font-medium hover:bg-gray-800 transition disabled:opacity-60"
        >
          {loading ? "Creating Account..." : "Sign Up"}
        </button>

        {/* Login Redirect */}
        <p className="text-center text-gray-700 text-sm mt-2">
          Already have an account?{" "}
          <Link
            href="/login"
            className="text-blue-600 font-medium cursor-pointer hover:underline"
          >
            Sign In
          </Link>
        </p>

        <p className="text-center text-gray-500 text-sm my-2">Or Sign Up With</p>

        {/* Google */}
        <button
          type="button"
          onClick={() => googleLogin()}
          className="flex items-center justify-center gap-2 border border-gray-200 rounded-lg py-3 hover:border-blue-500 transition"
        >
          <img
            src="https://unpkg.com/simple-icons@v10/icons/google.svg"
            alt="Google"
            className="w-5 h-5"
          />
          Continue with Google
        </button>

        {/* Facebook */}
        <button
          type="button"
          onClick={handleFacebookLogin}
          className="flex items-center justify-center gap-2 border border-gray-200 rounded-lg py-3 hover:border-blue-500 transition"
        >
          <svg className="w-5 h-5" fill="#1877F2" viewBox="0 0 24 24">
            <path d="M24 12.073c0-6.627-5.373-12-12-12s-12 5.373-12 12c0 5.99 4.388 10.954 10.125 11.854v-8.385H7.078v-3.47h3.047V9.43c0-3.007 1.792-4.669 4.533-4.669 1.312 0 2.686.235 2.686.235v2.953H15.83c-1.491 0-1.956.925-1.956 1.874v2.25h3.328l-.532 3.47h-2.796v8.385C19.612 23.027 24 18.062 24 12.073z" />
          </svg>
          Continue with Facebook
        </button>
      </form>
    </div>
  );
}
